import {captionAssistant} from './photo-caption.js';
import {validatePhoto,uploadPhoto,newRecordID} from './media-rules.js';
import {galleryGroups} from './gallery-groups.js';
export async function compressGalleryPhoto(file){validatePhoto(file);const src=URL.createObjectURL(file);try{const image=new Image();image.src=src;await image.decode();const scale=Math.min(1,1800/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.round(image.naturalWidth*scale);canvas.height=Math.round(image.naturalHeight*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const blob=await new Promise(r=>canvas.toBlob(r,'image/webp',.87));if(!blob)throw Error('Could not prepare '+file.name);return new File([blob],file.name.replace(/\.[^.]+$/,'')+'.webp',{type:'image/webp'});}finally{URL.revokeObjectURL(src);}}
export function galleryTools({host,editor,rows,list,sb,api,status,group,beforeBatch}){
 let dragged=null,orderDirty=false,busy=false,queue=[],captionBatch=0;const toolbar=host.querySelector('.collection-toolbar');
 const label=document.createElement('label');label.textContent='Bulk upload · up to 20 photos';const input=document.createElement('input');input.type='file';input.multiple=true;input.accept='image/jpeg,image/png,image/webp';label.append(input);toolbar.append(label);
 const save=document.createElement('button');save.textContent='Save photo order';save.disabled=true;toolbar.append(save);const help=document.createElement('p');help.className='form-note';help.textContent='Drag cards to rearrange them, or use Move earlier / Move later. Then choose Save photo order.';toolbar.after(help);
 const guard=e=>{if(busy||((orderDirty||queue.some(q=>!q.done))&&!confirm('Leave without saving the remaining gallery changes?'))){e.preventDefault();}};const unload=e=>{if(busy||orderDirty||queue.some(q=>!q.done)){e.preventDefault();e.returnValue='';}};window.addEventListener('beforeunload',unload);
 function reorder(from,to){if(busy||from===to)return;const a=rows.findIndex(r=>r.id===from),b=rows.findIndex(r=>r.id===to);if(a<0||b<0)return;const [item]=rows.splice(a,1);rows.splice(b,0,item);orderDirty=true;save.disabled=false;list();status('Order changed in this preview. Save photo order to publish it.');}
 save.onclick=async()=>{busy=true;save.disabled=true;try{const r=await sb.rpc('elan_reorder_gallery',{p_ids:rows.map(r=>r.id)});if(r.error)throw r.error;if(r.data!==rows.length)throw Error('The server did not confirm the new order.');rows.forEach((r,i)=>r.sort_order=i+1);orderDirty=false;status('Photo order saved.');}catch(e){status(e.message,true);}finally{busy=false;save.disabled=!orderDirty;}};
 function clear(){captionBatch++;for(const item of queue){item.captionHelp?.dispose();URL.revokeObjectURL(item.preview);}queue=[];input.value='';}
 input.onchange=async()=>{if(busy||beforeBatch&&!beforeBatch())return;if(orderDirty){status('Save the photo order before uploading.',true);input.value='';return;}if(queue.some(q=>!q.done)&&!confirm('Replace the unsaved upload queue?'))return;const files=[...input.files];try{if(files.length>20)throw Error('Choose up to 20 photos per batch.');files.forEach(validatePhoto);clear();queue=files.map(file=>({id:newRecordID(),file,preview:URL.createObjectURL(file),done:false}));editor.replaceChildren();const form=document.createElement('form');form.className='app-card bulk-gallery';const h=document.createElement('h2');h.textContent='Review your upload batch';form.append(h);const note=document.createElement('p');note.textContent='Every photo saves as a draft. Captions and descriptions are suggested from each photo. Review them, then publish each photo from its Edit form after review.';form.append(note);const select=document.createElement('select');select.setAttribute('aria-label','Group for this batch');for(const c of galleryGroups){const o=document.createElement('option');o.value=c;o.textContent=c;select.append(o);}select.value=group?.value||'People';form.append(select);
 for(const item of queue){const row=document.createElement('div');row.className='bulk-photo-row';const image=document.createElement('img');image.src=item.preview;image.alt='Upload preview';row.append(image);for(const [key,title,max] of [['title','Caption',160],['alt_text','Describe what is in this photo',400]]){const l=document.createElement('label');l.textContent=title;const field=document.createElement('input');field.required=true;field.maxLength=max;field.value='';item[key]=field; l.append(field);row.append(l);}const progress=document.createElement('p');progress.setAttribute('role','status');item.progress=progress;row.append(progress);form.append(row);const assistance=document.createElement('div');row.append(assistance);item.captionHelp=captionAssistant({sb,container:assistance,caption:item.title,description:item.alt_text});}
 const submit=document.createElement('button');submit.type='submit';submit.textContent='Upload as drafts';const cancel=document.createElement('button');cancel.type='button';cancel.className='secondary';cancel.textContent='Close batch';form.append(submit,cancel);cancel.onclick=()=>{if(busy)return;if(queue.some(q=>!q.done)&&!confirm('Discard the photos that have not been saved?'))return;clear();editor.replaceChildren();};
 form.onsubmit=async e=>{e.preventDefault();if(busy||!form.reportValidity())return;busy=true;captionBatch++;for(const item of queue)item.captionHelp?.dispose();form.inert=true;let failed=0;for(const item of queue){if(item.done)continue;try{item.progress.textContent='Preparing and uploading…';item.prepared??=await compressGalleryPhoto(item.file);item.uploaded??=await uploadPhoto(item.prepared,sb,api);const record={id:item.id,edition_slug:'2026',title:item.title.value.trim(),alt_text:item.alt_text.value.trim(),image_url:item.uploaded,category:select.value,credit:'',published:false,sort_order:Math.min(9999,Math.max(0,...rows.map(r=>r.sort_order))+1)};const saved=await api('admin-save',{table:'elan_media',record});if(saved.id!==item.id||saved.published!==false)throw Error('Save was not confirmed.');item.done=true;item.progress.textContent='Draft saved';item.title.disabled=true;item.alt_text.disabled=true;if(!rows.some(r=>r.id===saved.id))rows.push(saved);}catch(err){failed++;item.progress.textContent='Not saved: '+err.message;}}
 busy=false;form.inert=false;submit.disabled=!failed;submit.textContent=failed?'Retry remaining photos':'All drafts saved';list();status(failed?'Some photos need attention. Retry sends only the remaining photos.':'All photos saved as drafts. Open Edit photo to review and publish.',!!failed);};editor.append(form);editor.scrollIntoView({block:'start'});const batch=[...queue],batchID=++captionBatch;void(async()=>{for(const item of batch){if(batchID!==captionBatch||!queue.includes(item)||item.done)break;await item.captionHelp.setFile(item.file);}})();
 }catch(e){status(e.message,true);}};
 return {canLeave(){if(busy)return false;return !(orderDirty||queue.some(q=>!q.done))||confirm('Discard remaining gallery changes?');},decorate(card,row){card.draggable=true;card.addEventListener('dragstart',e=>{dragged=row.id;e.dataTransfer.setData('text/plain',row.id);});card.addEventListener('dragover',e=>e.preventDefault());card.addEventListener('drop',e=>{e.preventDefault();if(dragged)reorder(dragged,row.id);dragged=null;});const actions=document.createElement('div');actions.className='app-actions';for(const [label,delta] of [['Move earlier',-1],['Move later',1]]){const b=document.createElement('button');b.type='button';b.className='secondary';b.textContent=label;b.setAttribute('aria-label',label+': '+row.title);b.onclick=()=>{const i=rows.findIndex(r=>r.id===row.id),target=rows[i+delta];if(target)reorder(row.id,target.id)};actions.append(b);}card.append(actions);},dispose(){clear();document.removeEventListener('elan:admin-leave',guard);window.removeEventListener('beforeunload',unload);},canEdit(){if(busy)return false;if(orderDirty){status('Save the photo order before editing an entry.',true);return false;}if(queue.some(q=>!q.done)&&!confirm('Discard the remaining upload queue?'))return false;clear();return true;}};
}
